function SWEP:PlaySeq(seq, rate)
    local vm = self:GetOwner():GetViewModel()
    if not IsValid(vm) then return 0 end
    local s = vm:LookupSequence(seq)
    if s and s >= 0 then
        vm:SendViewModelMatchingSequence(s)
        local r = rate or 1
        vm:SetPlaybackRate(r)
        return vm:SequenceDuration(s) / r
    end
    return 0
end

